+import { point, distance } from '@turf/turf';
+
+export interface Coordinates {
+  latitude: number;
+  longitude: number;
+}
+
+export const EARTH_CIRCUMFERENCE_KM = 40075;
+
+export function normalizeLongitude(longitude: number): number {
+  const normalized = ((longitude + 180) % 360 + 360) % 360 - 180;
+  return Number(normalized.toFixed(6));
+}
+
+export function normalizeLatitude(latitude: number): number {
+  const clamped = Math.max(-90, Math.min(90, latitude));
+  return Number(clamped.toFixed(6));
+}
+
+export function computeAntipode(latitude: number, longitude: number): Coordinates {
+  return {
+    latitude: normalizeLatitude(-latitude),
+    longitude: normalizeLongitude(longitude + 180),
+  };
+}
+
+export function distanceBetweenKm(
+  from: Coordinates,
+  to: Coordinates,
+): number {
+  const fromPoint = point([from.longitude, from.latitude]);
+  const toPoint = point([to.longitude, to.latitude]);
+  return Number(distance(fromPoint, toPoint, { units: 'kilometers' }).toFixed(3));
+}
+
+export function toGeoPoint({ latitude, longitude }: Coordinates) {
+  return {
+    type: 'Point' as const,
+    coordinates: [Number(longitude.toFixed(6)), Number(latitude.toFixed(6))] as [number, number],
+  };
+}
