+function createListingSeed(
+  snapshots: LocationSnapshot[],
+  members: Member[],
+): AntipodeListing[] {
+  const listings: AntipodeListing[] = [];
+  for (const snapshot of snapshots) {
+    const snapshotAntipodeCoords: Coordinates = {
+      latitude: snapshot.antipodeLatitude,
+      longitude: snapshot.antipodeLongitude,
+    };
+    for (const member of members) {
+      if (member.visibilityScope !== 'public' || member.availabilityStatus !== 'available') {
+        continue;
+      }
+
+      const distanceKm = distanceBetweenKm(
+        snapshotAntipodeCoords,
+        {
+          latitude: member.homeLocation.coordinates[1],
+          longitude: member.homeLocation.coordinates[0],
+        },
+      );
+
+      listings.push({
