+function buildSeedData(): SeedData {
+  const members = createMemberSeed();
+  const snapshots = createSnapshotSeed(members);
+  const listings = createListingSeed(snapshots, members);
+
+  return {
+    members,
+    snapshots,
+    listings,
+    threads: [],
+    messages: [],
+    availabilityChanges: [],
+  };
+}
+
+export class MemoryStore {
+  private members = new Map<string, Member>();
+  private snapshots = new Map<string, LocationSnapshot>();
+  private listingsBySnapshot = new Map<string, AntipodeListing[]>();
+  private threads = new Map<string, ConversationThread>();
+  private messagesByThread = new Map<string, Message[]>();
+  private availabilityChanges: AvailabilityChangeLog[] = [];
+
+  constructor() {
+    this.reset();
+  }
+
+  reset(seed: SeedData = buildSeedData()): void {
+    this.members.clear();
+    this.snapshots.clear();
+    this.listingsBySnapshot.clear();
+    this.threads.clear();
+    this.messagesByThread.clear();
+    this.availabilityChanges = [];
+
+    seed.members.forEach((member) => this.members.set(member.id, member));
+    seed.snapshots.forEach((snapshot) => this.snapshots.set(snapshot.id, snapshot));
+    seed.listings.forEach((listing) => {
+      const existing = this.listingsBySnapshot.get(listing.snapshotId) ?? [];
+      existing.push(listing);
+      this.listingsBySnapshot.set(listing.snapshotId, existing);
+    });
+    seed.threads.forEach((thread) => this.threads.set(thread.id, thread));
+    seed.messages.forEach((message) => {
+      const messages = this.messagesByThread.get(message.threadId) ?? [];
+      messages.push(message);
+      this.messagesByThread.set(message.threadId, messages);
+    });
+    this.availabilityChanges = seed.availabilityChanges;
+  }
+
+  listMembers(): Member[] {
+    return [...this.members.values()];
+  }
+
+  getMemberById(memberId: string): Member | undefined {
+    return this.members.get(memberId);
+  }
+
+  listSnapshots(): LocationSnapshot[] {
+    return [...this.snapshots.values()];
+  }
+
+  getSnapshot(snapshotId: string): LocationSnapshot | undefined {
+    return this.snapshots.get(snapshotId);
+  }
+
+  upsertSnapshot(snapshot: LocationSnapshot): LocationSnapshot {
+    this.snapshots.set(snapshot.id, snapshot);
+    return snapshot;
+  }
+
+  listListingsForSnapshot(snapshotId: string): AntipodeListing[] {
+    return [...(this.listingsBySnapshot.get(snapshotId) ?? [])];
+  }
+
+  replaceListings(snapshotId: string, listings: AntipodeListing[]): void {
+    this.listingsBySnapshot.set(snapshotId, [...listings]);
+  }
+
+  upsertMember(member: Member): Member {
+    const existing = this.members.get(member.id);
+    if (existing) {
+      this.members.set(member.id, {
+        ...existing,
+        ...member,
+        updatedAt: isoNow(),
+      });
+      return this.members.get(member.id)!;
+    }
+    this.members.set(member.id, member);
+    return member;
+  }
+
+  recordAvailabilityChange(change: AvailabilityChangeLog): void {
+    this.availabilityChanges.push(change);
+  }
+
+  listThreadsForMember(memberId: string, status?: ThreadStatus): ConversationThread[] {
+    return [...this.threads.values()].filter((thread) => {
+      const isParticipant = thread.initiatorId === memberId || thread.recipientId === memberId;
+      const statusMatch = status ? thread.status === status : true;
+      return isParticipant && statusMatch;
+    });
+  }
+
+  getThread(threadId: string): ConversationThread | undefined {
+    return this.threads.get(threadId);
+  }
+
+  upsertThread(thread: ConversationThread): ConversationThread {
+    this.threads.set(thread.id, thread);
+    if (!this.messagesByThread.has(thread.id)) {
+      this.messagesByThread.set(thread.id, []);
+    }
+    return thread;
+  }
+
+  appendMessage(message: Message): Message {
+    const messages = this.messagesByThread.get(message.threadId) ?? [];
+    messages.push(message);
+    this.messagesByThread.set(message.threadId, messages);
+    const thread = this.threads.get(message.threadId);
+    if (thread) {
+      thread.lastMessageAt = message.sentAt;
+      thread.updatedAt = message.sentAt;
+    }
+    return message;
+  }
+
+  listMessages(threadId: string): Message[] {
+    return [...(this.messagesByThread.get(threadId) ?? [])];
+  }
+}
+
+export const memoryStore = new MemoryStore();
