+import { Injectable, BadRequestException } from '@nestjs/common';
+import {
+  AntipodeListingContract,
+  AntipodeLocation,
+} from '../../contracts';
+import {
+  memoryStore,
+  ListingGenerationOptions,
+  LocationSnapshot,
+  Member,
+  SnapshotCreationInput,
+} from '../../data/memory-store';
+import { AntipodeSearchRequestDto, AntipodeSearchResponseDto } from './dto/search.dto';
+
+interface ResolvedLocation {
+  latitude: number;
+  longitude: number;
+  displayLabel: string;
+  source: SnapshotCreationInput['source'];
+  userId?: string;
+  searchContext?: Record<string, unknown>;
+}
+
+const MANUAL_LOOKUP: Record<
+  string,
+  {
+    latitude: number;
+    longitude: number;
+    label?: string;
+  }
+> = {
+  // Seeded for prototype scenarios
+  lisbon: { latitude: 38.7223, longitude: -9.1393, label: 'Lisbon, Portugal' },
+  auckland: { latitude: -36.8485, longitude: 174.7633, label: 'Auckland, New Zealand' },
+  wellington: { latitude: -41.2865, longitude: 174.7762, label: 'Wellington, New Zealand' },
+  salamanca: { latitude: 40.9701, longitude: -5.6635, label: 'Salamanca, Spain' },
+};
+
+@Injectable()
+export class AntipodeService {
+  async search(request: AntipodeSearchRequestDto): Promise<AntipodeSearchResponseDto> {
+    const resolvedLocation = this.resolveLocation(request);
+
+    const snapshot = memoryStore.createSnapshot({
+      latitude: resolvedLocation.latitude,
+      longitude: resolvedLocation.longitude,
+      source: resolvedLocation.source,
+      displayLabel: resolvedLocation.displayLabel,
+      searchContext: resolvedLocation.searchContext,
+    });
+
+    const listings = memoryStore.generateListingsForSnapshot(
+      snapshot,
+      this.buildListingOptions(request),
+    );
+
+    const responseListings = this.toContractListings(listings);
+    const response: AntipodeSearchResponseDto = {
+      antipode: this.toAntipodeLocation(snapshot),
+      listings: responseListings,
+    };
+
+    if (responseListings.length === 0) {
+      response.emptyState =
+        'No opposite-side members are available yet. Check back soon or invite friends to join.';
+    }
+
+    return response;
+  }
+
+  private buildListingOptions(
+    request: AntipodeSearchRequestDto,
+  ): ListingGenerationOptions {
+    return {
+      includeUnavailable: request.includeUnavailable ?? false,
+    };
+  }
+
+  private resolveLocation(request: AntipodeSearchRequestDto): ResolvedLocation {
+    const { location } = request;
+    if (location.manual && location.manual.query) {
+      const manual = this.resolveManualLocation(location.manual.query);
+      if (!manual) {
+        throw new BadRequestException('Unable to resolve manual location query');
+      }
+      return manual;
+    }
+
+    if (location.device) {
+      return {
+        latitude: location.device.latitude,
+        longitude: location.device.longitude,
+        displayLabel: `Device location (~${Math.round(location.device.accuracyMeters)}m)`,
+        source: 'device',
+        searchContext: {
+          accuracyMeters: location.device.accuracyMeters,
+        },
+      };
+    }
+
+    throw new BadRequestException('Location payload missing');
+  }
+
+  private resolveManualLocation(query: string): ResolvedLocation | null {
+    const key = query.trim().toLowerCase();
+    const match = MANUAL_LOOKUP[key];
+    if (!match) {
+      return null;
+    }
+
+    return {
+      latitude: match.latitude,
+      longitude: match.longitude,
+      displayLabel: match.label ?? query,
+      source: 'manual_entry',
+      searchContext: {
+        query,
+      },
+    };
+  }
+
+  private toAntipodeLocation(snapshot: LocationSnapshot): AntipodeLocation {
+    return {
+      latitude: snapshot.antipodeLatitude,
+      longitude: snapshot.antipodeLongitude,
+      label: snapshot.antipodeLabel,
+    };
+  }
+
+  private toContractListings(listings: ReturnType<typeof memoryStore.listListingsForSnapshot>): AntipodeListingContract[] {
+    return listings
+      .map((listing) => {
+        const member: Member | undefined = memoryStore.getMemberById(listing.memberId);
+        if (!member) {
+          return undefined;
+        }
+        return {
+          memberId: member.id,
+          displayName: member.displayName,
+          intro: member.introText,
+          distanceKm: listing.distanceKm,
+          availability: member.availabilityStatus,
+          visibilityScope: member.visibilityScope,
+          lastActiveAt: member.lastActiveAt,
+        } satisfies AntipodeListingContract;
+      })
+      .filter((item): item is AntipodeListingContract => Boolean(item));
+  }
