+import { Canvas, useFrame } from '@react-three/fiber';
+import { useMemo, useRef } from 'react';
+import type { Mesh } from 'three';
+
+export interface AntipodePoint {
+  latitude: number;
+  longitude: number;
+  label?: string;
+}
+
+export interface AntipodeGlobeProps {
+  antipode?: AntipodePoint;
+  isAnimating?: boolean;
+}
+
+const RADIUS = 2;
+
+function latLonToVector3(latitude: number, longitude: number) {
+  const latRad = (latitude * Math.PI) / 180;
+  const lonRad = (longitude * Math.PI) / 180;
+  const x = RADIUS * Math.cos(latRad) * Math.cos(lonRad);
+  const y = RADIUS * Math.sin(latRad);
+  const z = RADIUS * Math.cos(latRad) * Math.sin(lonRad);
+  return [x, y, z] as const;
+}
+
+function GlobeSphere({ isAnimating }: { isAnimating: boolean }) {
+  const meshRef = useRef<Mesh>(null);
+
+  useFrame((_, delta) => {
+    if (!meshRef.current || !isAnimating) {
+      return;
+    }
+    meshRef.current.rotation.y += delta * 0.3;
+  });
+
+  return (
+    <mesh ref={meshRef}>
+      <sphereGeometry args={[RADIUS, 32, 32]} />
+      <meshStandardMaterial color="#1d3557" wireframe />
+    </mesh>
+  );
+}
+
+function AntipodeMarker({ antipode }: { antipode: AntipodePoint }) {
+  const position = useMemo(
+    () =>
+      latLonToVector3(antipode.latitude, antipode.longitude),
+    [antipode.latitude, antipode.longitude],
+  );
+
+  return (
+    <mesh position={position}>
+      <sphereGeometry args={[0.08, 16, 16]} />
+      <meshStandardMaterial color="#e76f51" />
+    </mesh>
+  );
+}
+
+export function AntipodeGlobe({ antipode, isAnimating = true }: AntipodeGlobeProps) {
+  return (
+    <div style={{ width: '100%', height: '320px' }}>
+      <Canvas camera={{ position: [0, 0, 6], fov: 50 }}>
+        <ambientLight intensity={0.6} />
+        <directionalLight position={[5, 5, 5]} intensity={0.6} />
+        <GlobeSphere isAnimating={isAnimating} />
+        {antipode ? <AntipodeMarker antipode={antipode} /> : null}
+      </Canvas>
+    </div>
+  );
+}
