    19	  const latRad = (latitude * Math.PI) / 180;
    20	  const lonRad = (longitude * Math.PI) / 180;
    21	  const x = RADIUS * Math.cos(latRad) * Math.cos(lonRad);
    22	  const y = RADIUS * Math.sin(latRad);
    23	  const z = RADIUS * Math.cos(latRad) * Math.sin(lonRad);
