+import {
+  BadRequestException,
+  ConflictException,
+  Injectable,
+  NotFoundException,
+} from '@nestjs/common';
+import {
+  Conversation,
+  ConversationSummary,
+  MemberProfile,
+  MessageContract,
+  ThreadStatus,
+} from '../../contracts';
+import {
+  memoryStore,
+  ConversationThread,
+  Member,
+  Message,
+  ThreadCreationInput,
+} from '../../data/memory-store';
+import { MessagingGateway } from '../../realtime/messaging.gateway';
+import {
+  ConversationStatusQueryDto,
+  SendMessageRequestDto,
+  StartConversationRequestDto,
+  UpdateConversationStatusRequestDto,
+} from './dto/conversation.dto';
+
+@Injectable()
+export class ConversationsService {
+  constructor(private readonly messagingGateway: MessagingGateway) {}
+
+  listConversations(query: ConversationStatusQueryDto): ConversationSummary[] {
+    const me = this.getCurrentMember();
+    const threads = memoryStore.listThreadsForMember(me.id, query.status);
+    return threads
+      .map((thread) => this.toConversationSummary(thread, me))
+      .sort((a, b) => new Date(b.lastMessageAt).getTime() - new Date(a.lastMessageAt).getTime());
+  }
+
+  getConversation(threadId: string): Conversation {
+    const me = this.getCurrentMember();
+    const thread = memoryStore.getThread(threadId);
+    if (!thread || !this.isParticipant(thread, me.id)) {
+      throw new NotFoundException('Conversation not found');
+    }
+    return this.toConversation(thread, me);
+  }
+
+  startConversation(payload: StartConversationRequestDto): Conversation {
+    const me = this.getCurrentMember();
+
+    if (payload.recipientId === me.id) {
+      throw new BadRequestException('Cannot start a conversation with yourself');
+    }
+
+    const recipient = memoryStore.getMemberById(payload.recipientId);
+    if (!recipient) {
+      throw new NotFoundException('Recipient not found');
+    }
+
+    const snapshot = memoryStore.getSnapshot(payload.originSnapshotId);
+    if (!snapshot) {
+      throw new BadRequestException('Origin snapshot not found');
+    }
+
+    const existingThread = memoryStore.findThreadBetweenMembers(me.id, recipient.id, 'active');
+    if (existingThread) {
+      throw new ConflictException('An active conversation already exists for this member pair');
+    }
+
+    const thread = memoryStore.createThread({
+      initiatorId: me.id,
+      recipientId: recipient.id,
+      initiatedFromSnapshot: snapshot.id,
+    });
+
+    const initialMessage = memoryStore.createMessage({
+      threadId: thread.id,
+      senderId: me.id,
+      body: payload.message,
+    });
+    this.notifyMessageCreated(initialMessage);
+
+    return this.toConversation(thread, me);
+  }
+
+  updateConversationStatus(
+    threadId: string,
+    payload: UpdateConversationStatusRequestDto,
+  ): Conversation {
+    const me = this.getCurrentMember();
+    const thread = memoryStore.getThread(threadId);
+    if (!thread || !this.isParticipant(thread, me.id)) {
+      throw new NotFoundException('Conversation not found');
+    }
+
+    const updated = memoryStore.updateThreadStatus(threadId, payload.status);
+    if (!updated) {
+      throw new NotFoundException('Conversation not found');
+    }
+
+    return this.toConversation(updated, me);
+  }
+
+  sendMessage(threadId: string, payload: SendMessageRequestDto): MessageContract {
+    const me = this.getCurrentMember();
+    const thread = memoryStore.getThread(threadId);
+    if (!thread || !this.isParticipant(thread, me.id)) {
+      throw new NotFoundException('Conversation not found');
+    }
+
+    if (thread.status !== 'active') {
+      throw new BadRequestException('Cannot send messages to inactive conversations');
+    }
+
+    const message = memoryStore.createMessage({
+      threadId,
+      senderId: me.id,
+      body: payload.body,
+    });
+    this.notifyMessageCreated(message);
+
+    return this.toMessageContract(message);
+  }
+
+  private getCurrentMember(): Member {
+    const members = memoryStore.listMembers();
+    if (!members.length) {
+      throw new BadRequestException('No members available in memory store');
+    }
+    return members[0];
+  }
+
+  private isParticipant(thread: ConversationThread, memberId: string): boolean {
+    return thread.initiatorId === memberId || thread.recipientId === memberId;
+  }
+
+  private toConversationSummary(thread: ConversationThread, me: Member): ConversationSummary {
+    const counterpartyId = thread.initiatorId === me.id ? thread.recipientId : thread.initiatorId;
+    const counterparty = memoryStore.getMemberById(counterpartyId);
+    if (!counterparty) {
+      throw new NotFoundException('Conversation participant missing');
+    }
+
+    const messages = memoryStore.listMessages(thread.id);
+    const lastMessage = messages.at(-1);
+
+    return {
+      id: thread.id,
+      participant: this.toMemberProfile(counterparty),
+      lastMessagePreview: lastMessage ? this.previewMessage(lastMessage.body) : '',
+      status: thread.status,
+      lastMessageAt: thread.lastMessageAt ?? thread.updatedAt,
+    };
+  }
+
+  private toConversation(thread: ConversationThread, me: Member): Conversation {
+    const participants = [
+      memoryStore.getMemberById(thread.initiatorId),
+      memoryStore.getMemberById(thread.recipientId),
+    ].filter((participant): participant is Member => Boolean(participant));
+
+    if (participants.length !== 2) {
+      throw new NotFoundException('Conversation participants missing');
+    }
+
+    const messages = memoryStore.listMessages(thread.id).map((message) =>
+      this.toMessageContract(message),
+    );
+
+    return {
+      id: thread.id,
+      participants: participants.map((participant) => this.toMemberProfile(participant)),
+      status: thread.status,
+      messages,
+      lastMessageAt: thread.lastMessageAt ?? thread.updatedAt,
+    };
+  }
+
+  private toMemberProfile(member: Member): MemberProfile {
+    return {
+      id: member.id,
+      displayName: member.displayName,
+      intro: member.introText,
+      visibilityScope: member.visibilityScope,
+      availability: member.availabilityStatus,
+      homeLocation: {
+        latitude: member.homeLocation.coordinates[1],
+        longitude: member.homeLocation.coordinates[0],
+        label: member.homeLocationLabel,
+      },
+      timeZone: member.timeZone,
+      lastActiveAt: member.lastActiveAt,
+    };
+  }
+
+  private previewMessage(body: string): string {
+    if (body.length <= 100) {
+      return body;
+    }
+    return `${body.slice(0, 97)}...`;
+  }
+
+  private toMessageContract(message: Message): MessageContract {
+    return {
+      id: message.id,
+      senderId: message.senderId,
+      body: message.body,
+      sentAt: message.sentAt,
+      readAt: message.readAt ?? undefined,
+      deliveryStatus: message.deliveryStatus,
+    };
+  }
+
+  private notifyMessageCreated(message: Message): void {
+    const contract = this.toMessageContract(message);
+    this.messagingGateway.broadcastMessage({
+      threadId: message.threadId,
+      message: contract,
+    });
+  }
+}
