+@WebSocketGateway({
+  namespace: 'messaging',
+  cors: {
+    origin: '*',
+  },
+})
+export class MessagingGateway {
+  @WebSocketServer()
+  private server!: Server;
+
+  broadcastMessage(payload: MessageEventPayload): void {
+    this.server.to(payload.threadId).emit('message:new', payload);
+    this.server.emit('message:any', payload);
+  }
+
+  @SubscribeMessage('thread:join')
+  handleJoinThread(
+    @ConnectedSocket() client: Socket,
+    @MessageBody() data: { threadId: string },
+  ): void {
+    if (!data?.threadId) {
+      return;
+    }
+    client.join(data.threadId);
+  }
+
+  @SubscribeMessage('thread:leave')
+  handleLeaveThread(
+    @ConnectedSocket() client: Socket,
+    @MessageBody() data: { threadId: string },
+  ): void {
+    if (!data?.threadId) {
+      return;
+    }
+    client.leave(data.threadId);
+  }
