+  appendMessage: (threadId: string, message: Message) => void;
+  setActiveThread: (threadId?: string) => void;
+  ensureSocket: () => Socket | undefined;
+}
+
+export const useConversationStore = create<ConversationStoreState>((set, get) => ({
+  summaries: [],
