+        [conversation.id]: conversation.messages,
+      };
+
+      const existingIndex = state.summaries.findIndex((summary) => summary.id === conversation.id);
+      const summaryUpdate: ConversationSummary = {
+        id: conversation.id,
+        participant:
+          conversation.participants.find((participant) => participant.id !== state.activeThreadId) ??
+          conversation.participants[0],
+        lastMessagePreview: conversation.messages.at(-1)?.body ?? '',
+        status: conversation.status,
+        lastMessageAt: conversation.lastMessageAt,
+      };
+
+      let summaries: ConversationSummary[];
+      if (existingIndex >= 0) {
+        summaries = [...state.summaries];
+        summaries[existingIndex] = {
+          ...summaries[existingIndex],
+          ...summaryUpdate,
+        };
+      } else {
+        summaries = [summaryUpdate, ...state.summaries];
+      }
+
+      return {
+        messagesByThread,
+        summaries,
+      };
+    }),
+
+  updateThreadStatus: (threadId, status) =>
+    set((state) => ({
+      summaries: state.summaries.map((summary) =>
+        summary.id === threadId ? { ...summary, status } : summary,
+      ),
+    })),
