    import('../components/globe/AntipodeGlobe').then(
      (module) => module.AntipodeGlobe,
    ),
  { ssr: false },
);

export default function HomePage() {
  const [manualQuery, setManualQuery] = useState('');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [isDetecting, setIsDetecting] = useState(false);

  const {
    data,
    mutateAsync: search,
    isPending: isSearching,
  } = useAntipodeSearch();

  const antipodeLocation: AntipodeLocation | undefined = data?.antipode;

  async function handleManualSearch(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!manualQuery.trim()) {
      setErrorMessage('Enter a city, region, or landmark to search.');
      return;
    }

    setErrorMessage(null);
    try {
      await search({
        location: {
          manual: {
            query: manualQuery.trim(),
          },
        },
      });
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : 'Search failed. Try again.');
    }
  }

  async function handleDetectClick() {
    setIsDetecting(true);
    setErrorMessage(null);
    try {
      const location = await detectDeviceLocation();
      await search({
        location: {
          device: location,
        },
        clientMetadata: {
          trigger: 'device-detect',
        },
      });
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : 'Unable to detect device location.');
    } finally {
      setIsDetecting(false);
    }
  }

  return (
    <main
      style={{
        minHeight: '100vh',
        padding: '4rem 1.5rem',
        background: 'linear-gradient(180deg, #0f172a 0%, #1e293b 40%, #f8fafc 100%)',
        color: '#0f172a',
        display: 'flex',
        justifyContent: 'center',
      }}
    >
      <div style={{ width: '100%', maxWidth: '960px' }}>
        <header style={{ textAlign: 'center', marginBottom: '2rem', color: '#f8fafc' }}>
          <h1 style={{ marginBottom: '0.5rem' }}>Discover Your Antipode Community</h1>
          <p style={{ margin: 0, fontSize: '1.1rem', color: '#cbd5f5' }}>
            Find people living on the opposite side of the world and start a conversation.
          </p>
        </header>

        <section
          style={{
            display: 'grid',
            gap: '2rem',
            gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
            alignItems: 'start',
          }}
        >
          <div
            style={{
              background: '#fff',
              borderRadius: '1.5rem',
              padding: '1.5rem',
              boxShadow: '0 10px 40px rgba(15, 23, 42, 0.15)',
            }}
          >
            <AntipodeGlobe
              antipode={
                antipodeLocation
                  ? {
                      latitude: antipodeLocation.latitude,
                      longitude: antipodeLocation.longitude,
                      label: antipodeLocation.label,
                    }
                  : undefined
              }
              isAnimating={!isSearching}
            />
            <div style={{ marginTop: '1rem', textAlign: 'center' }}>
              <p style={{ margin: 0, fontWeight: 600 }}>
                {antipodeLocation ? `Opposite point: ${antipodeLocation.label}` : 'Choose a location to see your antipode.'}
              </p>
            </div>
          </div>

          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '1.5rem',
            }}
          >
            <form
              onSubmit={handleManualSearch}
              style={{
                background: '#fff',
                borderRadius: '1.5rem',
                padding: '1.5rem',
                boxShadow: '0 10px 40px rgba(15, 23, 42, 0.1)',
              }}
            >
              <h2 style={{ marginTop: 0 }}>Search a location</h2>
              <p style={{ marginTop: 0, color: '#475569' }}>
                Enter a city or landmark and we will find who lives directly across the globe.
              </p>
              <label
                htmlFor="manual-location"
                style={{ display: 'block', fontWeight: 600, marginBottom: '0.5rem' }}
              >
                Location
              </label>
              <input
                id="manual-location"
                type="text"
                placeholder="e.g. Lisbon, Portugal"
                value={manualQuery}
                onChange={(event) => setManualQuery(event.target.value)}
                style={{
                  width: '100%',
                  borderRadius: '0.75rem',
                  border: '1px solid #cbd5f5',
                  padding: '0.75rem 1rem',
                  fontSize: '1rem',
                }}
              />
              <button
                type="submit"
                disabled={isSearching}
                style={{
                  marginTop: '1rem',
                  backgroundColor: '#2563eb',
                  color: '#fff',
                  border: 'none',
                  borderRadius: '0.75rem',
                  padding: '0.75rem 1rem',
                  fontSize: '1rem',
                  cursor: 'pointer',
                }}
              >
                {isSearching ? 'Searching…' : 'Find my antipode'}
              </button>
            </form>

            <button
              type="button"
              onClick={handleDetectClick}
              disabled={isDetecting || isSearching}
              style={{
                backgroundColor: '#0ea5e9',
                color: '#fff',
                border: 'none',
                borderRadius: '999px',
                padding: '0.75rem 1rem',
                fontSize: '1rem',
                cursor: 'pointer',
              }}
            >
              {isDetecting ? 'Detecting location…' : 'Use my current location'}
            </button>

            {errorMessage ? (
              <div
                role="alert"
                style={{
                  backgroundColor: '#fee2e2',
                  color: '#991b1b',
                  borderRadius: '0.75rem',
                  padding: '1rem',
                }}
              >
                {errorMessage}
              </div>
            ) : null}

            {data ? (
              data.listings.length > 0 ? (
                <MatchList listings={data.listings} />
              ) : (
                <EmptyState message={data.emptyState} />
              )
            ) : null}
          </div>
        </section>
      </div>
    </main>
  );
}
